package com.nxredux.mobile.achievements

/**
 * An `achievementsets` reply in the server's real shape: the game at the top, one core set nested under `Sets`.
 * [achievements] is the set's achievement objects, comma-separated, without the surrounding brackets.
 */
fun setsJson(gameId: Int, title: String = "Game", consoleId: Int = 5, achievements: String = ""): String =
    """{"Success":true,"GameId":$gameId,"Title":"$title","ConsoleId":$consoleId,"Sets":[""" +
        """{"Title":null,"Type":"core","AchievementSetId":$gameId,"GameId":$gameId,"Achievements":[$achievements],"Leaderboards":[]}]}"""

